// Normalize the raw HighLevel opportunity response into flat fields.
// Verify these paths against a real execution — HighLevel's response shape
// can vary slightly by API version.
// Note: this no longer reads from a specific trigger node, since this flow
// now has three possible entry points (schedule poll, webhook, manual test) —
// it relies entirely on the Get Opportunity Details API response instead.

// "Merge Deal + Pipelines" combines the opportunity data (input 0) with the
// pipelines list from "Get GHL Pipelines" (input 1) into one item, so both
// are available here on $json.

// Handles three possible shapes: { opportunities: [...] } (array),
// { opportunity: {...} } (singular), or a flat opportunity object itself.
const opp = $json.opportunities?.[0] ?? $json.opportunity ?? $json;

const dealName = opp.name ?? 'Unnamed Deal';
const dealId = opp.id ?? '';

// HighLevel's opportunity payloads only give pipelineId / pipelineStageId,
// not the human-readable names — those come from the pipelines list merged
// in from "Get GHL Pipelines".
const pipelines = $json.pipelines ?? [];

const pipelineId = opp.pipelineId ?? opp.pipeline_id ?? '';
const pipelineStageId = opp.pipelineStageId ?? opp.pipeline_stage_id ?? '';
const matchedPipeline = pipelines.find(p => p.id === pipelineId);
const matchedStage = matchedPipeline?.stages?.find(s => s.id === pipelineStageId);

const pipelineName = matchedPipeline?.name ?? opp.pipelineName ?? opp.pipeline_name ?? 'Unknown Pipeline';
const stageName = matchedStage?.name ?? opp.pipelineStageName ?? opp.pipeline_stage_name ?? 'Unknown Stage';

const dealValueRaw = opp.monetaryValue ?? opp.monetary_value ?? 0;
const dealValue = Number(dealValueRaw) || 0;
const contactName = opp.contact?.name ?? 'Unknown Contact';
const contactEmail = opp.contact?.email ?? '';
const ownerName = opp.assignedTo?.name ?? opp.assigned_to ?? 'Unassigned';
// HighLevel often only gives an assigned-user ID, not an email.
// Fall back to a shared distribution address until you wire up a user lookup.
const ownerEmail = opp.assignedTo?.email ?? 'user@example.com';
const dealSource = opp.source ?? '';

return [{
  json: {
    dealName,
    dealId,
    pipelineId,
    pipelineName,
    pipelineStageId,
    stageName,
    dealValue,
    contactName,
    contactEmail,
    ownerName,
    ownerEmail,
    dealSource
  }
}];

// Parse the agent's bullet-list output into structured data for
// Slack, Google Sheets, and Email.
const deal = $('Parse Deal Data').item.json;
const rawOutput = ($json.output ?? '').trim();

const actionItems = rawOutput
  .split('\n')
  .map(line => line.replace(/^[-•]\s*/, '').trim())
  .filter(line => line.length > 0);

const actionItemsText = actionItems.map(i => `- ${i}`).join('\n');

const valueFormatted = deal.dealValue
  ? new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(deal.dealValue)
  : 'N/A';

const slackText = `🆕 *New deal opened:* ${deal.dealName}\n` +
  `*Pipeline/Stage:* ${deal.pipelineName} → ${deal.stageName}\n` +
  `*Contact:* ${deal.contactName}\n` +
  `*Owner:* ${deal.ownerName}\n` +
  `*Value:* ${valueFormatted}\n\n` +
  `*Follow-up actions:*\n${actionItemsText}`;

const emailSubject = `Follow-up actions: ${deal.dealName}`;
const emailBody = `<p>A new deal was opened in <b>${deal.pipelineName}</b> (stage: ${deal.stageName}).</p>` +
  `<p><b>Contact:</b> ${deal.contactName} (${deal.contactEmail || 'no email on file'})<br/>` +
  `<b>Deal value:</b> ${valueFormatted}<br/>` +
  `<b>Owner:</b> ${deal.ownerName}</p>` +
  `<p><b>Follow-up actions:</b></p><ul>${actionItems.map(i => `<li>${i}</li>`).join('')}</ul>`;

return [{
  json: {
    ...deal,
    actionItems,
    actionItemsText,
    valueFormatted,
    slackText,
    emailSubject,
    emailBody,
    loggedAt: new Date().toISOString()
  }
}];

